INDEX_HTML = """<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><meta name="theme-color" content="#07643f"><title>章悟式∞競輪OS A/C</title>
<style>
:root{font-family:system-ui,-apple-system,"Noto Sans JP",sans-serif;color:#17212b;background:#f3f5f7}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0}.wrap{max-width:760px;margin:auto;padding:12px}.card{background:#fff;border-radius:20px;padding:18px;margin:14px 0;box-shadow:0 8px 24px #17212b12}h1{font-size:25px;margin:12px 2px 16px}.lead{line-height:1.6}.notice{padding:13px;border-radius:13px;background:#edf8f2;color:#075f3b;font-weight:750;line-height:1.55}.file-box{display:flex;align-items:center;justify-content:center;width:100%;min-height:88px;margin-top:16px;border:2px solid #087d49;border-radius:16px;background:#f2faf6;cursor:pointer;font-size:19px;font-weight:900;text-align:center;padding:12px}.native{position:absolute;width:1px;height:1px;opacity:0}.selected-list{margin:12px 0 0;padding:0;list-style:none}.selected-item{display:flex;align-items:center;gap:8px;padding:11px 6px;border-bottom:1px solid #e5eaed}.selected-name{min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.remove{border:0;border-radius:9px;padding:8px 10px;background:#eef1f3;color:#8a1b1b;font-weight:800}.count{margin:10px 2px;color:#52606a;font-weight:700}.field{margin-top:18px}.field-title{font-weight:900;font-size:17px}.field input{width:100%;height:52px;margin-top:7px;padding:10px 12px;border:1px solid #aeb8c2;border-radius:12px;font-size:18px}.submit{width:100%;min-height:68px;margin-top:22px;border:0;border-radius:16px;background:#087d49;color:white;font-size:19px;font-weight:900}.submit:disabled{opacity:.55}.status{min-height:24px;margin:16px 2px 0;font-weight:800}.error{color:#b11919;white-space:pre-wrap;font-weight:800;line-height:1.5}.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.result-card{background:#fff;border-radius:18px;padding:16px}.pick{display:grid;grid-template-columns:64px 1fr 74px;gap:8px;align-items:center;padding:11px 0;border-bottom:1px solid #e6eaed}.pair{font-size:21px;font-weight:900}.prob{font-size:14px;color:#52606a}.ev{text-align:right;font-weight:900}.meta{font-size:13px;color:#52606a;margin-top:4px}.empty{padding:14px 0;color:#6a747d;font-weight:800}@media(max-width:600px){.result-grid{grid-template-columns:1fr}.wrap{padding:10px}.card{padding:15px}.pick{grid-template-columns:58px 1fr 66px}}
</style></head><body><main class="wrap"><h1>章悟式∞競輪OS A/C</h1><section class="card"><p class="lead"><b>競輪.jpのPDFを3枚だけ追加してください。</b></p><div class="notice">①出走表・基本情報<br>②着度数／H・S回数<br>③2車単オッズ<br><br>順番は自由です。A方式とC方式を同時に計算します。</div>
<form id="form"><label class="file-box" for="pdfs">競輪.jpの3PDFを選択</label><input class="native" id="pdfs" name="files" type="file" accept="application/pdf" multiple required><div id="count" class="count">PDF 0/3枚</div><ul id="selected" class="selected-list"></ul>
<div class="field"><div class="field-title">専用PIN</div><input type="password" name="pin" autocomplete="current-password"></div><button class="submit" id="submit" type="submit">A方式＋C方式を計算</button></form><p id="status" class="status"></p><p id="error" class="error"></p></section>
<section id="result" hidden><div class="result-card"><h2>購入判定</h2><div id="decision"></div></div><div class="result-grid"><div class="result-card"><h2>A方式（購入判定）</h2><div class="meta">同ライン順目・人気5〜10位・10〜20倍・最大3点</div><div id="aResult"></div></div><div class="result-card"><h2>C方式（EV購入判定）</h2><div class="meta">個人能力→ライン・展開→Seed3156で10万回→全2車単確率→最後にオッズで推定EV。条件一致3点以上で最大5点、1〜2点は見送り。</div><div id="cResult"></div></div></div></section></main>
<script>
const form=document.querySelector('#form'),pdfInput=document.querySelector('#pdfs'),selected=document.querySelector('#selected'),count=document.querySelector('#count'),statusEl=document.querySelector('#status'),errorEl=document.querySelector('#error'),resultEl=document.querySelector('#result'),submitEl=document.querySelector('#submit'),decisionEl=document.querySelector('#decision'),aEl=document.querySelector('#aResult'),cEl=document.querySelector('#cResult');
let files=[];const key=f=>`${f.name}:${f.size}:${f.lastModified}`;
function sync(){const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));pdfInput.files=dt.files;count.textContent=`PDF ${files.length}/3枚`;selected.innerHTML=files.map((f,i)=>`<li class="selected-item"><span class="selected-name">${f.name}</span><button class="remove" type="button" data-index="${i}">削除</button></li>`).join('');}
pdfInput.addEventListener('change',()=>{const existing=new Set(files.map(key));for(const f of pdfInput.files){if(files.length>=3)break;if(!existing.has(key(f))){files.push(f);existing.add(key(f));}}sync();errorEl.textContent='';});
selected.addEventListener('click',e=>{const b=e.target.closest('.remove');if(!b)return;files.splice(Number(b.dataset.index),1);sync();});
function clearResult(){resultEl.hidden=true;decisionEl.innerHTML='';aEl.innerHTML='';cEl.innerHTML='';}
function renderA(items){if(!items||!items.length)return '<div class="empty">条件一致なし・見送り</div>';return items.map(v=>`<div class="pick"><div class="pair">${v.pair.join('-')}</div><div class="prob">人気 ${v.popularity_rank}位<br>オッズ ${Number(v.odds).toFixed(1)}</div><div class="ev">A</div></div>`).join('');}
function renderC(items){if(!items||!items.length)return '<div class="empty">順位データなし</div>';return items.map(v=>`<div class="pick"><div class="pair">${v.pair.join('-')}</div><div class="prob">予測確率 ${(Number(v.probability)*100).toFixed(2)}%<br>オッズ ${Number(v.odds).toFixed(1)}</div><div class="ev">EV<br>${Number(v.ev).toFixed(2)}<br>${v.purchase_label}</div></div>`).join('');}
function renderDecision(data){const a=data.strategies?.a?.candidates||[],c=data.strategies?.c?.purchase_candidates||[];if(a.length||c.length){const rows=[];if(a.length)rows.push(`A方式：${a.map(v=>v.pair.join('-')).join('・')}`);if(c.length)rows.push(`C方式：${c.map(v=>v.pair.join('-')).join('・')}`);return `<div class="notice">購入候補<br>${rows.join('<br>')}</div>`;}return '<div class="notice">見送り<br>A方式・C方式とも購入条件を満たしていません。</div>';}
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function requestCalculation(){
  for(let attempt=0;attempt<2;attempt++){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);
    try{
      const response=await fetch('/analyze-bundle',{method:'POST',body:new FormData(form),signal:controller.signal});
      const raw=await response.text();let data;
      try{data=JSON.parse(raw);}catch(_){data=null;}
      if([502,503,504].includes(response.status)&&attempt===0){statusEl.textContent='サーバー起動待ちです。自動でもう一度試しています…';await sleep(3000);continue;}
      if(!data)throw new Error('サーバー応答を確認できません。少し待ってからもう一度計算してください。');
      if(!response.ok)throw new Error(data.error?.message||data.detail||'PDFを確認してもう一度計算してください。');
      return data;
    }catch(err){
      if(err?.name==='AbortError')throw new Error('計算が混み合っています。少し待ってからもう一度計算してください。');
      throw err;
    }finally{clearTimeout(timer);}
  }
  throw new Error('サーバーを起動できませんでした。少し待ってからもう一度計算してください。');
}
form.addEventListener('submit',async e=>{e.preventDefault();errorEl.textContent='';clearResult();if(files.length!==3){errorEl.textContent='競輪.jpのPDFを3枚ちょうど追加してください。';return;}submitEl.disabled=true;statusEl.textContent='3PDFを判定して10万回計算中…';try{const data=await requestCalculation();decisionEl.innerHTML=renderDecision(data);aEl.innerHTML=renderA(data.strategies?.a?.candidates);cEl.innerHTML=renderC(data.strategies?.c?.candidates);resultEl.hidden=false;statusEl.textContent='計算完了';resultEl.scrollIntoView({behavior:'smooth',block:'start'});}catch(err){clearResult();statusEl.textContent='';errorEl.textContent=err?.message||'計算に失敗しました。少し待ってからもう一度お試しください。';}finally{submitEl.disabled=false;}});
</script></body></html>"""
